// Middleware
export default function ({ route, redirect }) {
  // If the redirect query parameter is present
  if (route.query.redirect) {
    // Wait for the page to be created
    this.app.router.onReady(() => {
      // Call the onServerPrefetch hook
      this.$options.fetch.call(this, this.$options.context).then(() => {
        // Redirect to the new page
        redirect(route.path)
      })
    })
  }
}
we wait for the router.onReady event to fire, indicating that the page has been created. 
Then, we call the fetch method and also trigger the onServerPrefetch hook. Once the fetch method has been completed, we can safely redirect to the new page.
